 class Selector
 {
 private:
     int            m_argc;
     char        ** m_argv;
     mutable bool   m_did_run;

 public:
     Selector(int argc, char* argv[])
     : m_argc(argc), m_argv(argv), m_did_run(false)
     { }

     bool operator()(const UnitTest::Test * const testCase) const
     {
         bool toRun = false;
         for (int i=1; i<m_argc; ++i)
