template <typename T>
class gsOptim : public gsOptimizer<T>
{
    using Base = gsOptimizer<T>;
public:

    typedef memory::unique_ptr<gsOptim> uPtr;

    typedef gsOptimBFGS<T>              BFGS;
    typedef gsOptimLBFGS<T>             LBFGS;
